27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	};
36	
37	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
38	
39	const policyBasePremium = (items: Item[]): number =>
40	  items.reduce((total, item) => total + basePremiumOf(item), 0);
41	
42	const quote = (step: Step): QuoteResult => {
43	  const basePremium = policyBasePremium(step.items);
44	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
45	
46	  return { premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE };
47	};
48	
49	export const runScenario = (scenario: Scenario): ScenarioResult => ({
50	  results: scenario.steps.map(quote),
51	});
