const quote = (step: Step): QuoteResult => {
  const basePremium = policyBasePremium(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const premiumBeforeFee = basePremium + firstInsuranceSurcharge;

  return { premium: premiumBeforeFee + PROCESSING_FEE };
};
